DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PSD 013", "old_status": "worked_needs_crop", "status": "ready", "question_id": "af937b79-1681-53cc-af5a-cf21f964bf1b", "stem": "The chart shows the age distribution of employees. If 481 employees are at least 30 and less than 40 years old, how many employees are there in total?", "choices": [{"key": "A", "text": "1150"}, {"key": "B", "text": "1200"}, {"key": "C", "text": "1550"}, {"key": "D", "text": "1300"}], "type": "mcq", "correct": "D", "explanation": "The 30–40 group is 37% of all employees. Therefore 0.37N = 481, so N = 481/0.37 = 1300. Check: 37% of 1300 is 481.", "topic": "Statistics, Probability & Data Analysis", "note": "Source page 154 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 154, "extra_sources": [], "crop": {"page": 154, "rect": [48, 245, 560, 534]}, "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:PSD 014", "old_status": "worked_shared_stimulus", "status": "ready", "question_id": "b2b2cdda-cd53-5e18-90ca-a5cf2484bb9b", "stem": "The chart shows the age distribution of employees. In which interval does the median age lie?", "choices": [{"key": "A", "text": "[20, 30)"}, {"key": "B", "text": "[30, 40)"}, {"key": "C", "text": "[40, 50)"}, {"key": "D", "text": "[50, 60)"}], "type": "mcq", "correct": "B", "explanation": "The cumulative percentage below age 30 is 28%. Below age 40 it is 28% + 37% = 65%. The middle (50th percentile) therefore lies in the interval [30, 40).", "topic": "Statistics, Probability & Data Analysis", "note": "Restored shared chart from PSD 013, page 154; options checked on page 155.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 155, "extra_sources": [], "crop": {"page": 154, "rect": [48, 245, 560, 534]}, "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:PSD 027", "old_status": "worked_needs_crop", "status": "ready", "question_id": "0e751a29-32ba-51b8-b47a-c0518be68f88", "stem": "A farm’s bee population is plotted against x, the number of years since 2012. The line of best fit is y = −56.429x + 525.71. Which choice is closest to the absolute difference between the actual and predicted bee population in 2017?", "choices": [{"key": "A", "text": "13"}, {"key": "B", "text": "56"}, {"key": "C", "text": "100"}, {"key": "D", "text": "525"}], "type": "mcq", "correct": "B", "explanation": "In 2017, x = 5 and the plotted observation is 300 bees. The prediction is −56.429(5) + 525.71 = 243.565. The absolute residual is |300 − 243.565| = 56.435, closest to 56.", "topic": "Statistics, Probability & Data Analysis", "note": "Source page 166 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 166, "extra_sources": [], "crop": {"page": 166, "rect": [144, 140, 565, 401]}, "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:PSD 028", "old_status": "worked_missing_choice", "status": "ready", "question_id": "236f8ffe-3c9e-520a-8a83-2f764a5928c4", "stem": "A farm’s bee population is modeled by y = −56.429x + 525.71, where x is years since 2012. In which year does the model predict that the population reaches zero?", "choices": [{"key": "A", "text": "2013"}, {"key": "B", "text": "2019"}, {"key": "C", "text": "2021"}, {"key": "D", "text": "2023"}], "type": "mcq", "correct": "C", "explanation": "Set y = 0: x = 525.71/56.429 ≈ 9.316. This is about 9.316 years after 2012, which falls in 2021.", "topic": "Statistics, Probability & Data Analysis", "note": "All four options, including the formerly missing D, confirmed in the full page 167.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 167, "extra_sources": []}, {"id": "clean:PSD 052", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "41fb810f-1f36-5cd0-954f-1c7574383482", "stem": "A data set has mean x and standard deviation α. If 5 is subtracted from every value, what are the new mean x′ and standard deviation α′?", "choices": [{"key": "A", "text": "x′ = 5x; α′ = α"}, {"key": "B", "text": "x′ = x + 5; α′ = α − 5"}, {"key": "C", "text": "x′ = x − 5; α′ = α"}, {"key": "D", "text": "x′ = x − 5; α′ = α − 5"}], "type": "mcq", "correct": "C", "explanation": "Subtracting 5 from every value also subtracts 5 from the mean. Each deviation from the new mean equals its original deviation, so the variance and standard deviation stay the same.", "topic": "Statistics, Probability & Data Analysis", "note": "Source page 186 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 186, "extra_sources": []}, {"id": "clean:PSD 055", "old_status": "worked_needs_crop", "status": "ready", "question_id": "1d7ba2f8-b12a-53ef-b246-af9227af500f", "stem": "The table classifies all 30 rabbits on a farm by size and color. One rabbit is selected at random. What is the probability that it is white?", "choices": [{"key": "A", "text": "4/14"}, {"key": "B", "text": "7/15"}, {"key": "C", "text": "1"}, {"key": "D", "text": "10/30"}], "type": "mcq", "correct": "B", "explanation": "There are 4 + 10 = 14 white rabbits out of 30. Therefore P(white) = 14/30 = 7/15.", "topic": "Statistics, Probability & Data Analysis", "note": "Source page 189 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 189, "extra_sources": [], "assets": {"html": "<table><thead><tr><th>Size</th><th>White</th><th>Brown</th><th>Gray</th></tr></thead><tbody><tr><td>Small</td><td>4</td><td>4</td><td>6</td></tr><tr><td>Big</td><td>10</td><td>2</td><td>4</td></tr></tbody></table>"}}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='source_review_20260928' AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_20260928','source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
